from pathlib import Path
import re,html
P=Path
css=re.search(r'<style>(.*?)</style>',P('index.html').read_text(encoding='utf-8'),re.S).group(1)
script=re.search(r'<script>.*?</script>',P('index.html').read_text(encoding='utf-8'),re.S).group(0)
svg="""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1080 610" role="img"><title>KillerCoda browser traffic through Traefik</title><defs><marker id="a" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto"><path d="M0 0 L9 3 L0 6" fill="none" stroke="#287b7b"/></marker></defs><style>text{font:16px system-ui;fill:#203a42}.b{fill:#fff;stroke:#96bdb4;stroke-width:2}.l{fill:none;stroke:#287b7b;stroke-width:2;marker-end:url(#a)}</style><rect width="1080" height="610" rx="20" fill="#eff7f2"/><text x="25" y="35">KILLERCODA ? generated browser hosts preserve the ingress traffic flow</text><rect class="b" x="25" y="65" width="285" height="90" rx="12"/><text x="42" y="98">Browser: generated platform URL</text><text x="42" y="130">Host header = session hostname</text><path class="l" d="M310 110 H365"/><rect class="b" x="370" y="65" width="300" height="90" rx="12"/><text x="387" y="98">KillerCoda Traffic / Ports proxy</text><text x="387" y="130">8080 / 8081 / 8082 / 8083</text><path class="l" d="M670 110 H725"/><rect class="b" x="730" y="65" width="320" height="90" rx="12"/><text x="747" y="98">4 forwards ? Traefik Service :80</text><text x="747" y="130">remote VM address: 0.0.0.0</text><path class="l" d="M890 155 V190 H540 V220"/><rect class="b" x="355" y="225" width="370" height="70" rx="12"/><text x="375" y="253">Traefik controller: 2 replicas</text><text x="375" y="280">Host rules select application Services</text>"""
for x,name,port,pods in [(20,'NGINX','8080','2 pods'),(285,'Prometheus','8081','2 pods'),(550,'Grafana','8082','2 pods'),(815,'Argo CD','8083','1 server pod')]:
 svg+=f'<path class="l" d="M540 295 V325 H{x+120} V355"/><rect class="b" x="{x}" y="360" width="245" height="80" rx="12"/><text x="{x+15}" y="390">Generated host for {port}</text><text x="{x+15}" y="420">Ingress ? {name}</text><path class="l" d="M{x+120} 440 V475"/><rect class="b" x="{x}" y="480" width="245" height="70" rx="12"/><text x="{x+15}" y="508">ClusterIP Service</text><text x="{x+15}" y="535">{name}: {pods}</text>'
svg+='<text x="25" y="588">Terminal curl can still use the original .lab.test Host rules on localhost:8080 inside the remote VM.</text></svg>'
P('docs/killercoda-architecture.svg').write_text(svg,encoding='utf-8')

parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Choose your lab environment • Git Bash &amp; KillerCoda</title><style>'+css+'</style><header><div class="eyebrow">START HERE / TWO ENVIRONMENTS, SAME LAB</div><h1>Your terminal.<br>Your playground.</h1><p class="lead">Use Git Bash on Windows with Docker Desktop, or Linux Bash in KillerCoda. The charts and GitOps learning objectives stay the same.</p><nav><a href="index.html">Section 1: Ingress</a><a href="lab2-argocd.html">Section 2: Argo CD</a><a href="#desktop">Git Bash setup</a><a href="#killercoda">KillerCoda setup</a><a href="#fork">Student forks</a></nav></header><main>']
def section(title,body,id=None):parts.append('<section'+(' id="'+id+'"' if id else '')+'><h2>'+title+'</h2><p>'+body+'</p>')
def code(title,text):parts.append('<h3>'+title+'</h3><div class="code"><button type="button">Copy</button><pre><code>'+html.escape(text)+'</code></pre></div>')
section('Choose the correct terminal','All primary command blocks in both lab guides use Bash. Invoke helpers with <code>bash scripts/name.sh</code>; no chmod or PowerShell is required. Git Bash is the terminal bundled with Git for Windows. KillerCoda provides Linux Bash in the browser. The older .ps1 helpers remain optional legacy files.')
parts.append('<table><tr><th>Setting</th><th>Git Bash + Docker Desktop</th><th>KillerCoda Linux Bash</th></tr><tr><td>Cluster context</td><td>docker-desktop</td><td>Keep the supplied context</td></tr><tr><td>Local access</td><td>localhost:8080 + .lab.test Host header</td><td>Same curl tests inside the remote terminal</td></tr><tr><td>Browser access</td><td>Windows hosts entries + localhost forward</td><td>Generated per-port URLs + matching Ingress hosts</td></tr><tr><td>Ports</td><td>127.0.0.1:8080</td><td>8080 NGINX, 8081 Prometheus, 8082 Grafana, 8083 Argo</td></tr><tr><td>GitOps source</td><td>Your public fork</td><td>Your public fork</td></tr></table></section>')
section('Git Bash on Windows','Install Git for Windows, kubectl and Helm; enable Kubernetes in Docker Desktop. Open Git Bash, not Windows PowerShell. Export MSYS_NO_PATHCONV=1 so Windows path conversion does not rewrite Kubernetes paths. This setting applies only to the current terminal, so use it in each new Git Bash terminal. Scripts also set it internally. Allow enough free cluster CPU/memory for six app pods plus the controller and Argo components. Inspect node capacity if scheduling is slow.','desktop')
code('Clone and select Docker Desktop','git clone https://github.com/vrdipu/ingress-lab.git\ncd ingress-lab\nexport MSYS_NO_PATHCONV=1\nkubectl config use-context docker-desktop\nkubectl get nodes\nhelm version --short\nbash scripts/deploy.sh')
code('Terminal A: keep local ingress access open','kubectl port-forward -n ingress-system svc/lab-ingress-traefik 8080:80 --address 127.0.0.1')
code('Terminal B: test the ingress routes','export MSYS_NO_PATHCONV=1\nbash scripts/validate.sh\nbash scripts/smoke-test.sh')
code('For desktop browser access: add to the Windows hosts file','127.0.0.1 nginx.lab.test prometheus.lab.test grafana.lab.test argocd.lab.test')
parts.append('<p>Edit <code>C:\\Windows\\System32\\drivers\\etc\\hosts</code> with an elevated text editor. Then use <code>http://nginx.lab.test:8080</code>, <code>http://prometheus.lab.test:8080</code>, <code>http://grafana.lab.test:8080</code> and, after Argo setup, <code>http://argocd.lab.test:8080</code>. Hosts-file edits are unnecessary for curl tests.</p></section>')
section('KillerCoda: start a clean Kubernetes playground','Open the <a href="https://killercoda.com/playgrounds/scenario/kubernetes">KillerCoda Kubernetes playground</a>. Wait for its nodes to be Ready, then run these commands in the browser terminal. Do not select docker-desktop: that context belongs to your Windows machine. Start with a clean playground so other ingress controllers or exercises do not compete with this lab. If Helm is absent, the Linux helper installs a pinned binary in ~/.local/bin after checking its downloaded SHA-256 checksum. It does not require sudo.','killercoda')
code('Clone, check tools and install Section 1','git clone https://github.com/vrdipu/ingress-lab.git\ncd ingress-lab\nbash scripts/install-helm-linux.sh\nexport PATH="$HOME/.local/bin:$PATH"\nkubectl config current-context\nkubectl get nodes\nbash scripts/deploy.sh')
code('Browser access: keep this launcher running','bash scripts/killercoda-access.sh')
parts.append('<p>The launcher reads <code>/etc/killercoda/host</code> and prints a generated URL for each installed app. It adds an Ingress with that actual browser hostname and forwards the corresponding port to the <strong>Traefik Service</strong>, not directly to the app. Use the printed URLs or the terminal menu’s <strong>Traffic / Ports</strong> entry. No hosts-file changes are needed. Port 8083 is skipped until Argo CD is installed.</p><div class="note">KillerCoda access URLs can be reached by anyone who has the URL. Use only disposable lab credentials and no production secrets. The environment is ephemeral and has a session limit; if it expires, clone and deploy again. Commit your learning changes to your fork before the session ends.</div>')
code('Second KillerCoda terminal: test real ingress routing','cd ingress-lab\nexport PATH="$HOME/.local/bin:$PATH"\nbash scripts/validate.sh\nbash scripts/smoke-test.sh\ncurl -i -H "Host: nginx.lab.test" http://127.0.0.1:8080/')
parts.append('<p>The curl command tests the original .lab.test rule; the browser uses an additional generated-host rule. Both go through Traefik → ClusterIP Service → ready app pod. Keep the launcher open while testing. Ctrl+C stops only its own port-forward processes. If a controller rollout ends a forward, rerun the launcher. Its logs are in ignored <code>.lab-runtime/</code>.</p></section>')
parts.append('<section><h2>KillerCoda traffic flow</h2><img src="docs/killercoda-architecture.svg" alt="Generated browser URLs enter platform ports and forwards to Traefik, which routes to Services and application pods."></section>')
section('Prepare your own GitOps repository','Students need write access to the repository Argo watches. Fork <a href="https://github.com/vrdipu/ingress-lab">vrdipu/ingress-lab</a> in GitHub first. Clone your fork from the start, or change origin in an existing clone as below. Replace YOUR-USERNAME with your real username. Public forks require no Argo repository credential. A GitHub password/Google password is not a Git HTTPS push credential; use your normal Git credential manager or a narrowly scoped GitHub token at the interactive prompt. Do not put credentials in remote URLs or copied commands.','fork')
code('Point all desired-state sources to your fork','git remote set-url origin https://github.com/YOUR-USERNAME/ingress-lab.git\nbash scripts/gitops-repository.sh https://github.com/YOUR-USERNAME/ingress-lab.git\ngit diff -- gitops/\ngit add gitops/bootstrap/project.yaml gitops/applications/\ngit commit -m "Point GitOps applications to my student fork"\ngit push -u origin main')
code('If Git asks for author identity, set it for this clone','git config user.name "Your Name"\ngit config user.email "YOUR-GITHUB-EMAIL"')
parts.append('<p>Commit and push these changes <strong>before</strong> running Argo setup. The script updates sourceRepos in the AppProject and repoURL in all three Applications. Chart paths and destination stay unchanged. Application policy changes still need kubectl apply after a Git commit because there is no parent Application watching the Application manifests.</p></section>')
section('Section 2 on either platform','Install Argo CD after Section 1 and after configuring your fork. The setup upgrades Traefik to ensure its Ingress status address is published, which can interrupt a forward attached to the old pod. Restart the access command for your platform after setup. All Applications start with automated sync explicitly disabled.')
code('Install Argo CD and the three Application definitions','bash scripts/argocd-setup.sh')
code('KillerCoda: stop the old access launcher, then restart it','bash scripts/killercoda-access.sh\n# Open the printed argocd URL (port 8083).')
code('Docker Desktop: restart the localhost forward','kubectl port-forward -n ingress-system svc/lab-ingress-traefik 8080:80 --address 127.0.0.1\n# Open http://argocd.lab.test:8080 after adding the Windows hosts entry.')
code('In another terminal, read the password and inspect the apps',"kubectl get secret argocd-initial-admin-secret -n argocd -o jsonpath='{.data.password}' | base64 --decode\nprintf '\\n'\nkubectl get applications -n argocd\n# Login as admin in the browser. Inspect the diff, then:\nbash scripts/argocd-sync.sh\nbash scripts/argocd-check.sh\nbash scripts/smoke-test.sh")
parts.append('<p>Continue with <a href="lab2-argocd.html">Section 2</a> for manual sync, Git changes, self-healing, pruning and Git revert. The access launcher sets Argo’s external URL for this session; the generated access Ingresses and URL are convenience runtime configuration outside the three Git-managed Applications. Do not commit ephemeral KillerCoda URLs into your reusable charts.</p></section>')
section('Common Bash and playground problems','Use these checks before changing manifests.')
for q,a in [('kubectl rewrites a path on Windows','Export MSYS_NO_PATHCONV=1 in that Git Bash terminal. Use the documented Bash scripts, which export it internally.'),('Script reports unexpected carriage returns','Use a fresh Git clone. .gitattributes enforces LF for scripts. If you copied a script through another editor, save it with Unix LF endings.'),('Browser returns 404 on KillerCoda','A Host header must match an Ingress. Run killercoda-access.sh and use its generated URL, not a .lab.test URL or an old session URL. Inspect the generated Ingress hosts.'),('Connection refused / HTTP 000','Keep the access launcher or desktop forward running. After a Traefik rollout, restart it. Check .lab-runtime forward logs and port conflicts.'),('Pods stay Pending or ImagePullBackOff','Inspect kubectl describe pod and events. Ensure a clean playground has enough allocatable resources, registry access and time to pull images. Keep two replicas for the learning objective; do not silently reduce them.'),('Killercoda Git changes do not reconcile','Push to the same fork referenced by all three Applications and allowed by the project. Check targetRevision, resolved SHA, comparison errors and manual/auto-sync policy.'),('KillerCoda session has expired','The environment and local files are temporary. Start a fresh playground and repeat setup from your committed fork. Do not expect the previous Argo installation or generated URLs to persist.')]:parts.append('<details open><summary>'+q+'</summary><p>'+a+'</p></details>')
parts.append('</section>')
section('What has actually been tested','Read <a href="docs/PORTABILITY-TEST-RESULTS.md">the portability report</a> for executed Git Bash and Linux checks and any untested external-environment details. The HTML guide itself does not require a running playground.')
parts.append('<p>Platform behavior references: <a href="https://killercoda.com/creators">KillerCoda network traffic documentation</a> and <a href="https://killercoda.com/faq">session FAQ</a>.</p></section></main><footer>Same charts • same GitOps loop • platform-specific access<span id="status" role="status" aria-live="polite"></span></footer>'+script+'</html>')
P('environments.html').write_text(''.join(parts),encoding='utf-8')
print('Created platform setup guide')
